remove_non_stat_visual_creator_traits.script:
const V=["Race","Body Type","Body Build","Body Trait","Skin Tone","Skin Color","Hair Style","Hair Color","Hair Color Pattern","Hair Detail","Facial Hair","Facial Features","Piercings","Accessories","Tattoos","Eyes","Eye Color","Eye Pattern","Outfit","Portrait Style","Image Style","Portrait Framing","Scene Background","Poses","Facial Expressions"],S=["attributes","skills","resources","abilities","startingItems","statModifiers","attributeModifiers","skillModifiers","resourceModifiers","modifiers","bonuses"];
function ne(v){return v!=null&&(Array.isArray(v)?v.length:typeof v==='object'?Object.keys(v).length:typeof v==='number'?v!==0:String(v).trim().length>0)}
function stat(n){try{let t=traits&&traits[n];if(!t)return true;for(let f of S)if(ne(t[f]))return true;return false}catch(e){return true}}
function scan(v,o){if(Array.isArray(v))v.forEach(x=>scan(x,o));else if(v&&typeof v==='object')Object.values(v).forEach(x=>scan(x,o));else if(typeof v==='string')o.push(v.trim())}
const p=check({type:'player-traits'})||{},all=[],vis=new Set();scan(p,all);
try{for(let c of V){let a=traitCategories&&traitCategories[c]&&traitCategories[c].traits;if(Array.isArray(a))a.forEach(x=>vis.add(String(x)))}}catch(e){}
const rm=[];for(let n of all)if(vis.has(n)&&!stat(n)&&!rm.includes(n))rm.push(n);
if(!rm.length)skip=true;else{for(let n of rm.slice(0,10))effects.push({type:'player-traits',operator:'remove',value:n});storage.nonStatVisualCreatorTraitsCleanedCount=(storage.nonStatVisualCreatorTraitsCleanedCount||0)+Math.min(10,rm.length);storage.nonStatVisualCreatorTraitsLastRemoved=rm.slice(0,10);}
